#!/usr/bin/env bash
# Generate steam_api_shim.def for the steam_api64 proxy/shim DLL.
#
# The shim ships AS  steam_api64.dll  next to the game, and the genuine Valve
# Steam API is renamed to  steam_api64_real.dll  (REAL_DLL below, the forward
# target). The game resolves Steamworks functions dynamically via GetProcAddress;
# the Windows loader transparently follows export FORWARDERS, so every name we
# forward resolves to the real DLL at runtime.
#
# Every name the game might resolve must be exported by the shim. We forward the
# full real-DLL export set (steam_exports.txt) and implement a small HOOKED set
# ourselves for logging.
set -euo pipefail
cd "$(dirname "$0")"

EXPORTS="steam_exports.txt"        # all exported names of the real steam_api64
REAL_DLL="steam_api64_real"        # forward target module (NO .dll suffix, DOT-FREE)
# NOTE: must be DOT-FREE. The PE loader splits a forwarder string on the LAST '.'
# to separate module from function; a name with a '.' looks like it already has
# an extension and '.dll' is NOT appended -> forward fails -> crash at load.
OUT="steam_api_shim.def"

# Functions we implement ourselves (typed trampolines w/ logging).
# Keep this list in sync with src/trampolines.cpp.
HOOKED=$(cat <<'EOF'
SteamAPI_ISteamUser_GetSteamID
SteamAPI_ISteamFriends_GetPersonaName
SteamAPI_ISteamApps_GetCurrentGameLanguage
SteamAPI_ISteamUser_GetAuthSessionTicket
SteamAPI_ISteamUser_GetAuthTicketForWebApi
SteamInternal_CreateInterface
SteamInternal_FindOrCreateUserInterface
SteamInternal_FindOrCreateGameServerInterface
EOF
)

is_hooked() { grep -qxF "$1" <<<"$HOOKED"; }

[ -f "$EXPORTS" ] || { echo "missing $EXPORTS (run extract_exports.sh <real dll>)" >&2; exit 1; }

{
  echo "; AUTO-GENERATED by generate_def.sh -- do not edit by hand."
  echo "; Shim proxy for steam_api64.dll. Forwards to $REAL_DLL.dll"
  echo "LIBRARY steam_api64"
  echo "EXPORTS"
  while IFS= read -r fn; do
    [ -z "$fn" ] && continue
    if is_hooked "$fn"; then
      echo "    $fn"                       # exported from our code
    else
      echo "    $fn = $REAL_DLL.$fn"       # loader forwards straight through
    fi
  done < <(sort -u "$EXPORTS")
} > "$OUT"

total=$(grep -cE '^    ' "$OUT")
fwd=$(grep -cE ' = ' "$OUT")
echo "wrote $OUT: $total exports ($fwd forwarded, $((total-fwd)) hooked)"
